<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Article extends Model {protected $guarded=[]; protected function casts():array{return ['legacy_published_at'=>'datetime','legacy_modified_at'=>'datetime'];}public function categories(){return $this->belongsToMany(EditorialCategory::class,'article_category');}public function tags(){return $this->belongsToMany(EditorialTag::class,'article_tag');}public function comments(){return $this->hasMany(Comment::class);}}
